commands.command:
if (Get-NetTCPConnection -State Listen -LocalPort 55438 -ErrorAction SilentlyContinue) { throw 'Local test port is occupied' }
$qaTunnel = Start-Process -FilePath 'C:\Program Files\PuTTY\plink.exe' -ArgumentList @('-load','hostinger2','-l','root','-batch','-N','-L','127.0.0.1:55438:127.0.0.1:55437') -WindowStyle Hidden -PassThru
[pscustomobject]@{pid=$qaTunnel.Id;start_time=$qaTunnel.StartTime.ToString('o');path=$qaTunnel.Path;has_exited=$qaTunnel.HasExited} | ConvertTo-Json

